KG42.register("rules-10645dcfea5f4bba96a67813",{"id":"23-hierarchical_market_structure::v141-c-R008","paper":"23-hierarchical_market_structure","record":{"rule_id":"v141-c-R008","mechanism_id":"v141-a-M01","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"The DNEM market clearing price is an input to the LA's WEM bidding vector, coordinating its decentralized bidding decision through a local price signal. Scope: Cross-market price coordination of LA l's WEM bidding using the DNEM market clearing price. Condition: LA l plays role “2,” exporting electricity from the DNEM to the WEM.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.price_signal","pricing.local"],"E":[{"edge_id":"v141-c-R008-E001","source":"pricing.local","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E011","v141-b-g01-E025"]}],"omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Cross-market price coordination of LA l's WEM bidding using the DNEM market clearing price.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E011","v141-b-g01-E025"]},"x":[{"variable_id":"x_psi_prime_l","symbol":"\\psi'_l","meaning":"LA l's WEM bidding strategy vector; the upper-level decision that is multiplied by the DNEM MCP in the WEM bid-vector equation (12).","kind":"operational","domain":"Bounded real vector satisfying \\underline{\\psi}'_l \u003c= \\psi'_l \u003c= \\bar{\\psi}'_l (source Eq. (11)); numeric bounds are not stated in the rule.","unit":null,"indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011"]},{"variable_id":"x_rho_prime_l","symbol":"\\rho'_l","meaning":"LA l's WEM bidding vector developed from the WEM bidding strategy and the DNEM MCP; determined by Eq. (12).","kind":"operational","domain":"Real bidding vector with source unit [$/MW]; no independent feasible interval is stated in Eq. (12).","unit":"$/MW","indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011"]}],"theta":[{"parameter_id":"theta_lambda_0","symbol":"\\lambda_0","meaning":"DNEM market clearing price (MCP); the load-balance Lagrange multiplier in the DNEM clearing problem and the price signal passed to the LA's WEM bid vector.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"$/MWh","indices":[],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011","v141-b-g01-E015","v141-b-g02-E20"]},{"parameter_id":"theta_psi_l_lower","symbol":"\\underline{\\psi}'_l","meaning":"Lower limit of LA l's WEM bidding strategy vector.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011"]},{"parameter_id":"theta_psi_l_upper","symbol":"\\bar{\\psi}'_l","meaning":"Upper limit of LA l's WEM bidding strategy vector.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011"]}],"phi":[{"constraint_id":"v141-c-R008-C001","kind":"procedural","role":"core","statement":"The DNEM market clearing price is an input to the LA's WEM bidding vector, coordinating its decentralized bidding decision through a local price signal. Scope: Cross-market price coordination of LA l's WEM bidding using the DNEM market clearing price. Condition: LA l plays role “2,” exporting electricity from the DNEM to the WEM.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E011","v141-b-g01-E025"]},{"constraint_id":"v141-c-R008-C002","kind":"mathematical","role":"core","statement":"For LA l under the source's role “2” scope, the WEM bidding vector equals the WEM bidding strategy multiplied by the DNEM market clearing price.","expression":"\\rho'_l = \\psi'_l * \\lambda_0","formalization_origin":"source","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":["x_rho_prime_l","x_psi_prime_l"],"parameter_refs":["theta_lambda_0"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011","v141-b-g01-E015","v141-b-g01-E025"]},{"constraint_id":"v141-c-R008-C003","kind":"mathematical","role":"supporting","statement":"For LA l in role “2,” the WEM bidding strategy is limited by the source-specified lower and upper bounds in Eq. (11).","expression":"\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["x_psi_prime_l"],"parameter_refs":["theta_psi_l_lower","theta_psi_l_upper"],"evidence_ids":["v141-b-g01-E000","v141-b-g01-E011"]}],"pi":[{"evidence_id":"v141-b-g01-E011","location":{"location_id":"src-fbc18f73e3-p04-c1r2__v141-a-M01-bidding","page":4,"printed_page":null,"section":"II-C LAs Objective","anchor_text":"of providing electricity to the distribution network. The LAs bidding vector in the DNEM is given in","equation_id":"(10)-(12)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"R'_l = \\max_{\\psi'_l,P_l^{exp}} \\left[ \\left(\\sum_{o\\in B_l^o} LMP'_o - \\lambda_0\\right) P_l^{exp} \\right] \\tag{10}\n\\underline{\\psi}'_l \\le \\psi'_l \\le \\bar{\\psi}'_l \\tag{11}\n\\rho'_l = \\psi'_l * \\lambda_0. \\tag{12}\nConsidering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12)."},{"evidence_id":"v141-b-g01-E025","location":{"location_id":"src-fbc18f73e3-p05-c2r4__v141-a-M01-coordination","page":5,"printed_page":null,"section":"III. Multilevel Complete Information Game","anchor_text":"p ∂Rl ψ′k+1 = ψ′kl + δ . (46) l ∂ψ′k l 5) The presented game is considered as a dynamic game as the ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The presented game is considered as a dynamic game as the LAs observe the actions of other market participants in one market before updating their bidding strategy in the other. Here, LAs consider the decision made by GENCOs once bidding in the DNEM. Similarly, LAs observe the decision made by microgrids once bidding in the WEM. The bidding vector of LAs in each market is determined based on the awarded dispatch and the price of electricity at the LAs’ bus in the other market. The observability indicator v is a binary parameter, which indicates that the LAs observed the actions of participants in the other market at each iteration. The bidding strategy of market participants update iteratively until the convergence"},{"evidence_id":"v141-b-g01-E000","location":{"location_id":"src-fbc18f73e3-p01-c1r4__v141-a-M01-participation","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"Variables Pj Generation dispatch of generator j [MW]. Pm Generation dispatch of microgrid m [MW]. Pe","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"P_j Generation dispatch of generator j [MW]. P_m Generation dispatch of microgrid m [MW]. P_l^{exp}, P_l^{imp} Power “exported from”/“imported to” distribution network electricity market (DNEM) by LA l [MW]. R_j Payoff function of GENCO j [$]. R_m Payoff function of microgrid m [$]. R_l, R'_l Payoff function of LA l in the DNEM/wholesale electricity market (WEM) [$]. \\rho_m, \\rho_l Bidding vector of microgrid m/LA l in the DNEM [$/MW]. \\rho'_j, \\rho'_l Bidding vector of GENCO j/LA l in the WEM [$/MW]. \\psi_m, \\psi_l Bidding strategy vector of microgrid m/LA l in the DNEM. \\psi'_j, \\psi'_l Bidding strategy vector of unit j of GENCO i/LA l in the WEM. \\lambda_0, \\lambda'_0, \\lambda_b^{'+}, \\lambda_b^{'-} Lagrange multipliers. B_j^o, B_l^o Set of buses o corresponds to the market participants j and l. \\bar{F}_b, \\underline{F}_b Minimum/maximum limits for power flow in branch b [MW]. P^D Total demand in the distribution network [MW]. P_o^{'D} Demand on bus o in the WEM [MW]. \\bar{P}_l^{exp}, \\underline{P}_l^{exp} Minimum/maximum power exported from the DNEM by LA l [MW]. \\bar{P}_l^{imp}, \\underline{P}_l^{imp} Minimum/maximum power imported to the DNEM by LA l [MW]. \\bar{P}_{(.)}, \\underline{P}_{(.)} Minimum/maximum generation dispatch [MW]. SF_b^o Shift factor of branch b with respect to injection at bus o. \\alpha(.), \\beta(.), \\gamma(.) Coefficients for generation cost function. \\bar{\\psi}(.), \\underline{\\psi}(.) Upper/lower limit of the bidding strategy vector in the DNEM. \\bar{\\psi}'(.), \\underline{\\psi}'(.) Upper/lower limit of the bidding strategy vector in the WEM."},{"evidence_id":"v141-b-g01-E015","location":{"location_id":"src-fbc18f73e3-p04-c2r2__v141-a-M01-clearing","page":4,"printed_page":null,"section":"II-E DNEM Clearing Process","anchor_text":"y As min ρm ∗Pm + ρl ∗Pimpl (19) m l 7) s.t. Pm + Pimpl = PD + Pexpl λ0 (20) m l l 8) P m ≤Pm ≤¯Pm ∀","equation_id":"(19)-(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The DNO minimizes the operational cost of distribution network as shown by\n\\min \\sum_m \\rho_m * P_m + \\sum_l \\rho_l * P_l^{imp} \\tag{19}\ns.t. \\sum_m P_m + \\sum_l P_l^{imp} = P^D + \\sum_l P_l^{exp} \\quad \\lambda_0 \\tag{20}\n\\underline{P}_m \\le P_m \\le \\bar{P}_m \\quad \\forall m \\tag{21}\n\\underline{P}_l^{imp} \\le P_l^{imp} \\le \\bar{P}_l^{imp} \\quad \\forall l. \\tag{22}\nThe load balance in the distribution network is shown in (20). The constraints on the awarded generation for microgrids and the imported power by the LA are shown in (21) and (22), respectively. Here, \\lambda_0 is the Lagrangian multiplier for the generation and load balance constraint in the distribution network as it is assumed that the electricity delivery is not limited by the line congestions."},{"evidence_id":"v141-b-g02-E20","location":{"location_id":"src-fbc18f73e3-p07-c2r4__v141-a-M01-pricing","page":7,"printed_page":"1872","section":"IV. Case Study","anchor_text":"ed. market. re, Case 3) Lower marginal cost of electricity in microgrids of with no congestion in th","equation_id":null,"figure_id":null,"table_id":"Table III","image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"Case 1) Higher Marginal Cost of Electricity in Microgrids With No Congestion in the Wholesale Electricity Market: In this case, the microgrids provide higher marginal cost for electricity compared to the GENCOs as shown in Table II. The bidding strategies and the awarded dispatches for each market participant are listed in Table III. Since there is no congestion in the WEM, the MCP is 80 $/MWh, while the MCP in the DNEM is 140 $/MWh. In this case, the lower price of electricity in the WEM provides incentives for the LA to import electricity from this market to the DNEM."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-coordination","v141-a-M01-participation"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E025","quote":"The bidding vector of LAs in each market is determined based on the awarded dispatch and the price of electricity at the LAs’ bus in the other market."},{"evidence_id":"v141-b-g01-E011","quote":"Considering role “2,” the LA l maximizes the payoff function which is shown in (10), subjected to the constraints on the bidding vector (11). The MCP (\\lambda_0) in the DNEM is the marginal cost of providing electricity to the WEM. The bidding vector of LA l in the WEM is shown in (12)."}]],"C2_formalization":{"graph_sha256":"c700b8244c0969911bbe4dd72aa154f32b9ae81b5408ace049c6a20c432d0763","applicability":"formalized","reason":"Formalized the directly supported price-signal relation in Eq. (12): the LA's WEM bid vector equals its WEM bidding strategy multiplied by the DNEM MCP lambda_0. The role-2 payoff (10) and the role-selection condition involving LMP'_o remain preserved in C001 but are not formalized because the frozen graph has no WEM LMP node. B evidence remains unreviewed.","bindings":[{"object_id":"x_psi_prime_l","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R008-E001"],"rationale":"psi'_l is the LA's WEM bidding-strategy decision at coordination.price_signal; edge E001 supplies the DNEM price input from pricing.local that enters the bid-vector relation."},{"object_id":"x_rho_prime_l","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R008-E001"],"rationale":"rho'_l is the LA's WEM bid vector produced by Eq. (12) at coordination.price_signal; its value depends on lambda_0 received through edge E001."},{"object_id":"theta_lambda_0","node_ids":["pricing.local"],"edge_ids":["v141-c-R008-E001"],"rationale":"lambda_0 is the DNEM MCP under pricing.local and is the price signal on edge E001 from pricing.local to coordination.price_signal."},{"object_id":"theta_psi_l_lower","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"The lower bound constrains psi'_l at coordination.price_signal; it does not itself depend on the price-input edge."},{"object_id":"theta_psi_l_upper","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"The upper bound constrains psi'_l at coordination.price_signal; it does not itself depend on the price-input edge."},{"object_id":"v141-c-R008-C001","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R008-E001"],"rationale":"The procedural statement asserts that the DNEM MCP is an input to the LA's WEM bidding vector, matching edge E001 from pricing.local to coordination.price_signal; it remains not formalized."},{"object_id":"v141-c-R008-C002","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R008-E001"],"rationale":"Equation (12) formalizes the edge: rho'_l at coordination.price_signal equals psi'_l times lambda_0 from pricing.local."},{"object_id":"v141-c-R008-C003","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"The bound on psi'_l belongs to the coordination decision at coordination.price_signal and does not require a separate graph edge."}],"revision_requests":["To formalize the full role-2 payoff (10) and role-selection condition, C.1 would need a WEM locational-marginal-price node and an appropriate edge/condition involving LMP'_o and P_l^{exp}; the frozen graph currently contains only pricing.local and coordination.price_signal for this rule."]}},"quarantined_references":[]}});
